"""Appendices: forms, gate sheet, quick commands."""
from sections_a import table, callout

def forms():
    h = "<h3>A.1 Gate sign-off sheet (one per project – print and keep in 02-projects/…/)</h3>" + table(["Gate","Stage","Evidence attached","Self-check done","Peer review by","Approver","Date","Signature"],
      [(f"G{n}", s, "☐", "☐", "", a, "", "") for n, s, a in [(1,"Check the idea","Owner"),(2,"Write what we build","PO + Customer"),(3,"Plan how it works","Tech Lead + Owner"),(4,"Design screens","PO + Customer"),(5,"Set up project","Tech Lead"),(6,"Build it","PO + Tech Lead"),(7,"Test it","QA Lead + PO"),(8,"Secure it","Tech Lead (+Owner for risk)"),(9,"Cost & price","Owner + Finance"),(10,"Put it online","Tech Lead + Owner"),(11,"Show, sell, deliver","Customer + Owner"),(12,"Keep it running","Tech Lead")]])
    h += "<h3>A.2 Project record (create on day 1 of every project)</h3>" + table(["Field","Value"],[(x,"") for x in ["Project ID (P001)","Product name","Product Owner","Tech Lead","Developers","QA owner","Customer contact","Budget (₹)","Planned delivery date","Approved scope version","Production cost estimate","Sales price","Expected margin %","Current stage / last gate signed","Risk register link"]])
    h += "<h3>A.3 Pull Request template</h3><pre>## What changed\n(one or two sentences)\n\n## Why\nTicket: #__\n\n## How to test\n1. ...\n2. ...\n\n## Screenshots (if screen changed)\n\n## Checklist\n- [ ] Tests added/updated and passing\n- [ ] Inputs validated on the server\n- [ ] No secrets or customer data\n- [ ] Docs updated\n- [ ] Time logged</pre>"
    h += "<h3>A.4 Bug report template</h3>" + table(["Field","Content"],[("Title","Short and specific"),("Environment","staging / production · browser · device"),("Steps to reproduce","1. 2. 3."),("Expected result",""),("Actual result",""),("Screenshot / video",""),("Severity","Critical / High / Medium / Low"),("Found by / date","")])
    h += "<h3>A.5 Change Request form</h3>" + table(["Field","Content"],[("CR ID","CR-P001-001"),("Requested by / date",""),("Description",""),("Business reason",""),("Technical impact",""),("Cost impact (₹)",""),("Timeline impact (days)",""),("Security impact",""),("Customer approval","Name / date / signature"),("Product Owner decision","Approved / Rejected / Later")])
    h += "<h3>A.6 Test case template</h3>" + table(["ID","Requirement","Steps","Expected","Actual","Pass/Fail","Tester / date"],[("TC-001","PRD 4.2 booking conflict","1 Book 10:15. 2 Book 10:15 again","Second booking refused; next 3 slots offered","","",""),("TC-002","","","","","","")])
    h += "<h3>A.7 Weekly report (every Friday)</h3>" + table(["Field","Content"],[(x,"") for x in ["Name / week","Completed (ticket links)","Pending","Blockers (what, since when, who can help)","Hours by project ID and stage","Quality issues found","Next week's deliverables"]])
    h += "<h3>A.8 Deployment checklist</h3>" + table(["Check","Done"],[(x,"☐") for x in ["Version tagged and release notes written","Database backed up","Migrations run on production","Environment settings checked (names only)","DNS verified with dig","HTTPS and redirect verified with curl","Email SPF/DKIM/DMARC pass","Smoke tests green","Monitoring and alert test received","Rollback steps ready","Owner approval recorded (G10)"]])
    h += "<h3>A.9 Handover checklist</h3>" + table(["Item","Done"],[(x,"☐") for x in ["User manual and admin manual delivered","Training sessions completed and attendance recorded","Support contacts, hours and escalation sent","Acceptance form signed","Invoice issued","Subscription terms and renewal date recorded","Consent obtained before any logo/testimonial use","Credentials transferred only via the password manager"]])
    h += "<h3>A.10 Incident report</h3>" + table(["Field","Content"],[(x,"") for x in ["Incident ID / level","Start and end time","What happened","Customer impact","Root cause","Fix applied","How we prevent it","Owner · reviewed by · date"]])
    return h

def commands():
    rows = [("Where am I?","<code>pwd</code>  (Windows PowerShell: <code>Get-Location</code>)"),("List files","<code>ls</code>  /  <code>dir</code>"),("Go into / out of a folder","<code>cd folder</code>  /  <code>cd ..</code>"),
     ("Clone a repository","<code>git clone git@github.com:ORG/repo.git</code>"),("See what changed","<code>git status</code>  ·  <code>git diff</code>"),("Update main","<code>git switch main && git pull</code>"),
     ("New branch","<code>git switch -c feature/12-short-name</code>"),("Save changes","<code>git add .</code> then <code>git commit -m \"feat: what changed\"</code>"),("Send to GitHub","<code>git push -u origin feature/12-short-name</code>"),
     ("Undo uncommitted edits to a file","<code>git restore path/to/file</code>"),("See history","<code>git log --oneline -10</code>"),("Install / run / test / build","<code>npm ci</code> · <code>npm run dev</code> · <code>npm test</code> · <code>npm run build</code>"),
     ("Lint","<code>npm run lint</code>"),("Check vulnerable libraries","<code>npm audit</code>"),("DNS lookups","<code>dig +short example.com A</code> · <code>dig +short example.com MX</code> · <code>dig +short example.com TXT</code>"),
     ("Check HTTPS redirect","<code>curl -I http://example.com</code>  ·  <code>curl -I https://example.com</code>"),("Check a port is answering","Open the URL in the browser or <code>curl -I http://localhost:3000</code>")]
    return table(["I want to…","Command"], rows) + callout("warn","Before you press Enter","If a command deletes, resets or overwrites something, stop and ask the Tech Lead. Never run commands you do not understand, especially ones copied from the internet or containing 'sudo' or 'force'.")
